TextPanel::TextPanel(QWidget* parent)
    : QWidget(parent)
    , _ui(std::make_unique<Ui::TextPanel>())
    , _tracker_fs(new UnitTracker(Inkscape::Util::UNIT_TYPE_LINEAR, this))
    , _tracker_lh(new UnitTracker(Inkscape::Util::UNIT_TYPE_LINEAR, this))
{
    _ui->setupUi(this);

    // Allow horizontal shrinking
    setMinimumWidth(0);
    setSizePolicy(QSizePolicy::Ignored, QSizePolicy::Preferred);

    // Decoration options popup (created in code; the widget is not in the .ui).
    // Must exist before setupConnections() wires its signals.
    _decorationOptions = new DecorationOptions(this);
    _decorationPopup = new PopupMenu(this);
    _decorationPopup->setContent(_decorationOptions);

    // Font browser popup (created in code; the widget is not in the .ui).
    _fontList = new FontList(this);
    _fontListPopup = new PopupMenu(this);
    _fontListPopup->setContent(_fontList);

    setupUnitTrackers();
    setupConnections();
    setupFontDiscovery();

    // Limit the variable-font axes area to about 4.5 axis rows;
    // when there are more than 4 axes, then 1/2 will indicate overflow.
    static int four = _ui->fontVariations->measureHeight(4);
    static int five = _ui->fontVariations->measureHeight(5);
    int row = five - four;
    _variableFontsMaxHeight = four + row * 0.65; // height tweaked to uncover just enough of the last row
}

TextPanel::~TextPanel() = default;

